<template>
  <main class="hypit-workbench">
    <header class="workbench-header">
      <div class="heading"><router-link to="/?media=video">← 云图库</router-link><div><span class="eyebrow">HYPIT · 0.2.16</span><h1>{{ project?.name || '完整视频工程' }}</h1></div><span class="revision">v{{ revision }}</span></div>
      <div class="actions"><span class="status">{{ busy ? '正在处理…' : dirty ? '源文件尚未保存' : lease ? '已保存 · 持有编辑权' : '只读查看' }}</span><button v-if="!lease" :disabled="busy" @click="acquire">获取编辑权</button><template v-else><button :disabled="busy" @click="handoffOpen=true">交接</button><button :disabled="busy" @click="release">释放</button></template><button v-if="mode==='timeline'" :disabled="!lease||busy" @click="applyTemplate('current')">开启完整工程</button><button class="primary" :disabled="!lease||busy||dirty" @click="exportProject">构建 / 导出</button></div>
    </header>
    <a-alert v-if="error" :message="error" type="error" show-icon closable @close="error=''"/>
    <a-alert v-if="mode==='timeline'" message="当前仍是基础剪辑项目。开启完整工程后可编辑所有原生组件；历史版本可恢复原剪辑模式。" type="info"/>
    <a-alert v-if="dirty&&sourceRevision<revision" :message="`项目已更新至 v${revision}，本地草稿仍基于 v${sourceRevision}。请复制保留草稿后重新载入；旧草稿不能覆盖新版本。`" type="warning" show-icon/>
    <nav class="workbench-tabs" aria-label="工程视图"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" @click="switchTab(item.id)">{{item.label}}</button><router-link v-if="mode==='timeline'" :to="`/video/editor/${id}?basic=1`">基础剪辑</router-link><button :disabled="!lease||busy||dirty" @click="cloneProject">创建工程变体</button></nav>
    <div class="workbench-content" :class="{'studio-layout':tab==='studio'}">
      <section class="workspace">
        <div v-if="tab==='studio'" class="studio-view"><div class="view-caption"><span>原生 Studio · 预览 / 语义时间线 / 属性 / 评论 / 产物</span><button @click="studioKey++">重新加载预览</button></div><iframe :key="studioKey" ref="studio" :src="`${videoBase}/projects/${id}/studio/`" title="完整 Hypit Studio" @load="studioLoaded"/></div>
        <div v-else-if="tab==='source'" class="source-view">
          <aside class="file-list"><span class="eyebrow">工程文件</span><button v-for="name in Object.keys(files)" :key="name" :class="{selected:name===selectedFile}" @click="selectedFile=name">{{name}}</button><div class="new-file"><input v-model="newFile" aria-label="新文件路径" placeholder="章节/画面.svml"/><button :disabled="!lease" @click="addFile">＋</button></div><label>运行入口<select v-model="entry" :disabled="!lease" @change="dirty=true"><option v-for="name in Object.keys(files).filter(n=>n.endsWith('.svrun'))" :key="name">{{name}}</option></select></label><button :disabled="!lease||['main.svml','main.svs','build.svrun',entry].includes(selectedFile)" @click="deleteFile">删除当前文件</button><p>文件集合和素材引用随版本保存。编译失败时保留上一个版本。</p></aside>
          <div class="code-pane"><div class="code-toolbar"><strong>{{selectedFile}}</strong><div><button :disabled="busy" @click="discardDraft">{{dirty?'放弃草稿并载入最新版本':'重新载入'}}</button><button :disabled="busy" @click="analyze('check')">校验</button><button :disabled="busy" @click="analyze('plan')">执行计划</button><button class="primary" :disabled="!lease||busy||!dirty" @click="saveSources">保存源工程</button></div></div><textarea v-model="files[selectedFile]" :readonly="!lease||busy" :aria-label="`源码 ${selectedFile}`" spellcheck="false" @input="dirty=true"/><details v-if="analysis" open class="analysis"><summary>编译 / 计划结果</summary><pre>{{analysis}}</pre></details></div>
        </div>
        <div v-else-if="tab==='catalog'" class="catalog-view"><aside><input v-model="search" aria-label="搜索组件" placeholder="搜索组件 / caption / media…"/><button v-for="item in filteredPackages" :key="item.name" :class="{selected:selectedPackage?.name===item.name}" @click="openPackage(item)">{{item.name}}</button></aside><article v-if="selectedPackage"><div class="article-heading"><h2>{{selectedPackage.name}}</h2><button :disabled="busy" @click="loadVocabulary">查看真实语法</button></div><p>以下内容来自固定版本的内置组件文档。</p><pre class="documentation">{{selectedPackage.documentation}}</pre><details v-if="syntax" open><summary>属性、输出与可用示例</summary><pre>{{syntax}}</pre></details></article><article v-else><h2>原生组件目录</h2><p>选择组件查看其真实文档、属性和示例。样式、时序和组合由 Hypit 编译器执行。</p></article></div>
        <div v-else-if="tab==='templates'" class="template-view"><span class="eyebrow">工程起点</span><h2>从素材开始编排</h2><p>应用模板会生成一个新版本；当前版本和素材仍可从历史中恢复。</p><label>语义配音素材<select v-model="semanticVoice" aria-label="语义配音素材"><option value="">选择已上传的配音</option><option v-for="asset in assets.filter(a=>a.kind==='audio')" :key="asset.id" :value="asset.id">{{asset.name}}</option></select></label><textarea v-model="semanticText" aria-label="配音对应台词" placeholder="应用逐字字幕模板时，输入此配音实际对应的台词"/><div class="template-grid"><article v-for="item in templateList" :key="item.id"><span class="template-icon">{{item.id==='split-screen'?'◫':item.id==='portrait'?'▯':'▤'}}</span><h3>{{item.name}}</h3><p>{{item.description}}</p><button :disabled="!lease||busy" @click="applyTemplate(item.id)">应用到工程</button></article></div></div>
        <div v-else-if="tab==='tasks'" class="tasks-view"><div class="article-heading"><h2>构建与产物</h2><input v-model="snapshotFrames" aria-label="截图帧" placeholder="截图帧：0,24,48"/><button :disabled="!lease||busy||dirty" @click="captureFrames">精确帧截图</button><button @click="refreshRuns">刷新</button></div><article v-for="run in runs" :key="run.id" class="run-card"><div><strong>{{run.kind}} · {{runLabel(run.status)}}</strong><span>v{{run.revision}} · {{new Date(run.created_at).toLocaleString()}}</span></div><p v-if="run.error" class="run-error">{{run.error}}</p><p v-if="run.result?.answer">{{run.result.answer}}</p><div class="actions"><button v-if="['queued','running'].includes(run.status)" :disabled="!lease" @click="cancelRun(run)">取消后续执行</button><button v-if="['error','awaiting_authorization'].includes(run.status)" :disabled="!lease" @click="retryRun(run)">恢复 / 重试</button><button v-if="['unknown','lost','cancelled','error'].includes(run.status)" :disabled="!lease||busy" @click="retryRun(run,true)">明确重新执行</button><button v-if="buildOf(run)" @click="inspectBuild(run,'inspect')">Build 详情</button><button v-if="buildOf(run)" @click="inspectBuild(run,'logs')">日志</button><button v-if="exportOf(run)?.objectKey" :disabled="!lease" @click="saveToGallery(run)">保存成片到图库</button></div><div v-for="(artifact,index) in artifactsOf(run)" :key="`${artifact.name}-${index}`" class="artifact"><strong>{{artifact.name}}</strong><small>{{artifact.mediaType}} · {{(artifact.size/1024).toFixed(1)}} KiB</small><video v-if="artifact.mediaType?.startsWith('video/')" controls preload="metadata" :src="artifactUrl(run,index)"/><audio v-else-if="artifact.mediaType?.startsWith('audio/')" controls preload="metadata" :src="artifactUrl(run,index)"/><img v-else-if="artifact.mediaType?.startsWith('image/')" :src="artifactUrl(run,index)" :alt="artifact.name"/><a :href="artifactUrl(run,index)" target="_blank" rel="noopener">打开产物</a></div></article><p v-if="!runs.length">尚无构建任务。</p><pre v-if="analysis" class="analysis">{{analysis}}</pre></div>
        <div v-else class="history-view"><div class="article-heading"><h2>版本与运行环境</h2><button :disabled="busy" @click="analyze('doctor')">环境诊断</button></div><article v-for="item in versions" :key="item.revision" class="version-row"><span>v{{item.revision}}</span><p>{{item.message}}</p><small>{{new Date(item.created_at).toLocaleString()}}</small><button :disabled="!lease||busy||item.revision===revision" @click="restore(item.revision)">恢复为新版本</button></article><pre v-if="analysis" class="analysis">{{analysis}}</pre></div>
      </section>
      <aside class="project-sidebar">
        <section><div class="sidebar-heading"><h2>素材</h2><span>{{assets.length}}</span><button :disabled="uploading" @click="fileInput?.click()">＋ 上传</button></div><input ref="fileInput" type="file" accept="video/*,image/*,audio/*" multiple hidden @change="upload"/><div v-for="asset in assets" :key="asset.id" class="asset-row"><img v-if="asset.posterKey" :src="assetMedia(id,asset.id,'poster')" :alt="asset.name"/><span v-else class="audio-icon">♫</span><div><strong>{{asset.name}}</strong><small>{{asset.kind}} · {{asset.frames ? (asset.frames/24).toFixed(2)+'s' : `${asset.width}×${asset.height}`}}</small><code>{{asset.id}}</code></div></div><p v-if="uploading">正在检查、转换并保存素材…</p></section>
        <section class="agent-panel"><span class="eyebrow">对话编排</span><p>修改原生工程、查询组件语法，或生成素材后加入编排。</p><div v-for="(item,index) in chat" :key="index" class="chat-message" :class="item.role">{{item.text}}</div><textarea v-model="prompt" aria-label="工程编辑指令" placeholder="保留这段实景，增加中文标题，并在结尾添加轻微闪光…"/><button class="primary" :disabled="!lease||busy||!prompt.trim()||dirty" @click="sendMessage">执行编辑</button></section>
        <section class="model-panel"><span class="eyebrow">自建模型素材</span><select v-model="modelTool" aria-label="生成模型"><option value="generate_image">Qwen Image · 生图 / 编辑</option><option value="generate_video">LTX · 文生 / 图生视频</option><option value="synthesize_speech">IndexTTS · 配音</option></select><select v-if="modelTool!=='synthesize_speech'" v-model="referenceAssetId" aria-label="参考素材"><option value="">无参考图</option><option v-for="asset in assets.filter(a=>a.kind==='image')" :key="asset.id" :value="asset.id">{{asset.name}}</option></select><select v-else v-model="voiceName" aria-label="配音音色"><option v-for="voice in voices" :key="voice">{{voice}}</option></select><textarea v-model="modelPrompt" aria-label="生成描述" placeholder="描述画面或输入配音文案"/><button :disabled="!lease||!modelPrompt.trim()||busy" @click="generate">生成并保存素材</button></section>
      </aside>
    </div>
    <a-modal v-model:open="handoffOpen" title="交接编辑权" :confirm-loading="busy" @ok="handoff"><label>接收成员 ID<input v-model="targetId"/></label></a-modal>
  </main>
</template>

<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { videoApi, videoBase, assetMedia, type VideoAsset } from '@/api/videoEditor'
import { CollaborationGate, leaseFromProject, invalidatesEditing } from '@/utils/videoCollaboration'
const snapshotFrames=ref('0,24,48')
const id=String(useRoute().params.id),router=useRouter(),sessionId=crypto.randomUUID()
const project=ref<any>(),revision=ref(1),mode=ref('timeline'),source=ref<any>(),files=ref<Record<string,string>>({}),entry=ref('build.svrun'),selectedFile=ref('main.svml'),newFile=ref(''),dirty=ref(false),lease=ref<any>(),busy=ref(false),error=ref(''),tab=ref('studio'),studio=ref<HTMLIFrameElement>(),studioKey=ref(0),assets=ref<VideoAsset[]>([]),fileInput=ref<HTMLInputElement>(),uploading=ref(false),analysis=ref(''),packages=ref<any[]>([]),selectedPackage=ref<any>(),search=ref(''),syntax=ref(''),templateList=ref<any[]>([]),runs=ref<any[]>([]),versions=ref<any[]>([]),prompt=ref(''),chat=ref<{role:string;text:string}[]>([]),handoffOpen=ref(false),targetId=ref(''),modelTool=ref('generate_image'),modelPrompt=ref(''),referenceAssetId=ref(''),voices=ref(['speaker1_a_cn_16k.wav']),voiceName=ref('speaker1_a_cn_16k.wav')
const tabs=[{id:'studio',label:'完整 Studio'},{id:'source',label:'源文件'},{id:'catalog',label:'组件目录'},{id:'templates',label:'模板'},{id:'tasks',label:'构建与产物'},{id:'history',label:'版本 / 环境'}]
const filteredPackages=computed(()=>packages.value.filter(p=>`${p.name} ${p.summary}`.toLowerCase().includes(search.value.toLowerCase())))
let studioReady=false,disconnected=false
let renewal:ReturnType<typeof setInterval>,poller:ReturnType<typeof setInterval>
const collaboration=new CollaborationGate()
function context(){if(!lease.value)throw Error('请先获取编辑权');return {expectedRevision:revision.value,sessionId,epoch:lease.value.epoch,idempotencyKey:crypto.randomUUID()}}
function fail(e:unknown){disconnected=!(e as any).status||(e as any).status>=500;error.value=(e as Error).message;if(invalidatesEditing(e)){lease.value=undefined;sendContext()}}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){fail(e);if((e as any).status===409)await refresh().catch(fail)}finally{busy.value=false}}
function sendContext(){studio.value?.contentWindow?.postMessage({type:'gallery-context',context:lease.value&&studioReady?context():null},location.origin)}
const sourceRevision=ref(1),semanticText=ref(''),semanticVoice=ref('')
async function loadSources(force=false){const current=await videoApi(`/projects/${id}/sources`);if(!force&&dirty.value||current.revision<sourceRevision.value)return;sourceRevision.value=current.revision;source.value=current.source;files.value={ 'main.svml':current.source['main.svml'],'main.svs':current.source['main.svs'],'build.svrun':current.source['build.svrun'],...current.source.files};entry.value=current.source.entry||'build.svrun';if(!(selectedFile.value in files.value))selectedFile.value=entry.value;dirty.value=false}
async function discardDraft(){await action(()=>loadSources(true))}
async function refresh(){const value=await videoApi(`/projects/${id}`);if(disconnected){error.value='';disconnected=false}lease.value=collaboration.reconcile(lease.value,leaseFromProject(value.project),sessionId,value.serverTime);if(value.revision<revision.value){sendContext();return}const changed=value.revision>revision.value;project.value=value.project;mode.value=value.mode;assets.value=value.assets;revision.value=value.revision;runs.value=value.runs.map((r:any)=>({...r,result:typeof r.result==='string'?JSON.parse(r.result):r.result}));if(changed){studioReady=false;sendContext();studioKey.value++;if(!dirty.value)await loadSources()}sendContext()}
async function acquire(){await action(async()=>{const acquired=await videoApi(`/projects/${id}/lease`,{action:'acquire',sessionId});if(collaboration.accept(acquired,acquired.serverTime))lease.value=acquired;await refresh();if(!dirty.value)await loadSources();sendContext()})}
async function release(){await action(async()=>{if(lease.value)await videoApi(`/projects/${id}/lease`,{action:'release',sessionId,epoch:lease.value.epoch});lease.value=undefined;sendContext()})}
async function handoff(){await action(async()=>{await videoApi(`/projects/${id}/lease`,{action:'handoff',sessionId,epoch:lease.value.epoch,targetId:targetId.value});lease.value=undefined;handoffOpen.value=false;sendContext()})}
function candidate(){return {...source.value,mode:'hypit',state:source.value.state,files:files.value,entry:entry.value}}
async function saveSources(){await action(async()=>{const result=await videoApi(`/projects/${id}/sources`,{...context(),expectedRevision:sourceRevision.value,source:candidate()},'PUT');revision.value=result.revision;mode.value='hypit';dirty.value=false;await loadSources();sendContext();studioKey.value++})}
function addFile(){const name=newFile.value.trim();if(!name||name in files.value)return;files.value[name]=name.endsWith('.json')?'{}\n':'';selectedFile.value=name;newFile.value='';dirty.value=true}
function deleteFile(){delete files.value[selectedFile.value];selectedFile.value=entry.value;dirty.value=true}
async function analyze(kind:string){await action(async()=>{analysis.value=JSON.stringify(await videoApi(`/projects/${id}/sources/${kind}`,{source:candidate()}),null,2)})}
async function applyTemplate(name:string){if(dirty.value){error.value='请先保存当前源文件，再应用模板';return}await action(async()=>{const result=await videoApi(`/projects/${id}/hypit/template`,{...context(),template:name,...(name==='semantic'?{args:{text:semanticText.value,voiceId:semanticVoice.value}}:{})});revision.value=result.revision;await refresh();await loadSources();studioKey.value++;tab.value='studio'})}
async function switchTab(name:string){tab.value=name;try{if(name==='catalog'&&!packages.value.length)packages.value=(await videoApi('/hypit/catalog')).packages;if(name==='templates'&&!templateList.value.length)templateList.value=await videoApi('/hypit/templates');if(name==='history')versions.value=await videoApi(`/projects/${id}/versions`);if(name==='tasks')await refreshRuns()}catch(e){fail(e)}}
function openPackage(item:any){selectedPackage.value=item;syntax.value=''}
async function loadVocabulary(){await action(async()=>{syntax.value=JSON.stringify(await videoApi(`/projects/${id}/hypit/vocabulary/${selectedPackage.value.name}`),null,2)})}
async function restore(target:number){if(dirty.value){error.value='请先保存未提交的源码';return}await action(async()=>{await videoApi(`/projects/${id}/restore`,{...context(),revision:target});await refresh();await loadSources();studioKey.value++})}
async function upload(e:Event){uploading.value=true;try{for(const file of Array.from((e.target as HTMLInputElement).files||[])){const form=new FormData();form.append('file',file);assets.value.push(await videoApi(`/projects/${id}/assets`,form))}}catch(e){fail(e)}finally{uploading.value=false;(e.target as HTMLInputElement).value=''}}
function runLabel(status:string){return ({queued:'排队',running:'执行中',done:'完成',error:'失败',cancelled:'已取消',unknown:'结果未知',lost:'任务丢失',awaiting_authorization:'等待恢复'} as Record<string,string>)[status]||status}
function exportOf(run:any){return run.kind==='agent'?run.result?.export:['export','snapshot'].includes(run.kind)?run.result:undefined}
function buildOf(run:any){return exportOf(run)?.buildId||run.steps?.find((s:any)=>s.build_id)?.build_id}
function artifactsOf(run:any){const result=exportOf(run);return result?.artifacts|| (result?.objectKey?[{...result,name:'final.video',mediaType:'video/mp4'}]:[])}
function artifactUrl(run:any,index:number){return `${videoBase}/runs/${run.id}/artifacts/${index}/media`}
async function refreshRuns(){await refresh();for(const run of runs.value.filter(r=>r.status==='running'||r.status==='done'&&!r.result)){const detail=await videoApi(`/runs/${run.id}`);Object.assign(run,detail)}}
async function cloneProject(){await action(async()=>{const result=await videoApi(`/projects/${id}/variants`,{...context(),name:project.value.name+' · 变体'});await router.push(`/video/hypit/${result.id}`)})}
async function captureFrames(){await action(async()=>{const frames=snapshotFrames.value.split(',').map(v=>Number(v.trim()));if(frames.some(v=>!Number.isSafeInteger(v)||v<0))throw Error('请输入整数帧，以英文逗号分隔');await videoApi(`/projects/${id}/snapshots`,{...context(),frames});await refreshRuns()})}
async function exportProject(){await action(async()=>{await videoApi(`/projects/${id}/exports`,context());tab.value='tasks';await refreshRuns()})}
async function cancelRun(run:any){await action(async()=>{await videoApi(`/runs/${run.id}/cancel`,context());await refreshRuns()})}
async function retryRun(run:any,regenerate=false){await action(async()=>{await videoApi(`/runs/${run.id}/retry`,{...context(),regenerate});await refreshRuns()})}
async function inspectBuild(run:any,kind:string){await action(async()=>{analysis.value=JSON.stringify(await videoApi(`/projects/${id}/hypit/builds/${buildOf(run)}/${kind}`),null,2)})}
async function saveToGallery(run:any){await action(async()=>{const result=await videoApi('/videos',{...context(),projectId:id,revision:exportOf(run).revision,runId:run.id,name:project.value.name});await router.push(`/video/${result.id}`)})}
async function sendMessage(){await action(async()=>{chat.value.push({role:'user',text:prompt.value});await videoApi(`/projects/${id}/messages`,{...context(),message:prompt.value,selection:{}});prompt.value='';tab.value='tasks';await refreshRuns()})}
async function generate(){await action(async()=>{const args:any=modelTool.value==='synthesize_speech'?{text:modelPrompt.value,spk_name:voiceName.value}:{prompt:modelPrompt.value};if(referenceAssetId.value)Object.assign(args,modelTool.value==='generate_image'?{referenceAssetIds:[referenceAssetId.value]}:{referenceAssetId:referenceAssetId.value});await videoApi(`/projects/${id}/generate`,{...context(),tool:modelTool.value,args});modelPrompt.value='';tab.value='tasks';await refreshRuns()})}
function studioLoaded(){studioReady=true;sendContext()}
function studioMessage(e:MessageEvent){if(e.origin!==location.origin||e.source!==studio.value?.contentWindow)return;if(e.data?.type==='gallery-studio-ready')sendContext();if(e.data?.type==='gallery-studio-error'){fail(Object.assign(new Error(e.data.message),{code:e.data.code,status:e.data.status}));void refresh().catch(fail)}if(e.data?.type==='gallery-studio-committed'){if(Number.isSafeInteger(e.data.revision)&&e.data.revision>revision.value)revision.value=e.data.revision;void refresh().then(()=>{if(!dirty.value)void loadSources()}).catch(fail)}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('message',studioMessage);window.addEventListener('beforeunload',beforeUnload);try{await refresh();await loadSources();const value=await videoApi('/voices');const list=Array.isArray(value)?value:value.voices;if(Array.isArray(list)&&list.length){voices.value=list.map((v:any)=>typeof v==='string'?v:v.name).filter(Boolean);if(!voices.value.includes(voiceName.value))voiceName.value=voices.value[0]!}}catch(e){fail(e)}renewal=setInterval(()=>{const current=lease.value;if(current)void videoApi(`/projects/${id}/lease`,{action:'renew',sessionId,epoch:current.epoch}).then(value=>{if(lease.value===current&&collaboration.accept(value,value.serverTime))lease.value=value}).catch(e=>{if(lease.value===current)fail(e)})},20000);poller=setInterval(()=>{if(!busy.value)void refresh().catch(fail)},5000)})
onUnmounted(()=>{clearInterval(renewal);clearInterval(poller);window.removeEventListener('message',studioMessage);window.removeEventListener('beforeunload',beforeUnload);if(lease.value)void videoApi(`/projects/${id}/lease`,{action:'release',sessionId,epoch:lease.value.epoch}).catch(()=>{})})
</script>

<style scoped>
.workbench-content.studio-layout{grid-template-columns:minmax(0,1fr)}
.studio-layout .project-sidebar{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-height:none}
.studio-layout .studio-view{overflow:auto}
.studio-layout .studio-view iframe{min-width:960px}
@media(max-width:700px){.studio-layout .project-sidebar{display:block}}
.hypit-workbench{--bg:#11191d;--panel:#192329;--line:#314149;--text:#e5eeec;--muted:#94aaa9;--accent:#b9e5b2;background:var(--bg);color:var(--text);margin:-16px -24px;padding:20px;min-height:calc(100vh - 90px);font-family:'Microsoft YaHei UI',sans-serif}.workbench-header,.heading,.actions,.sidebar-heading,.article-heading,.code-toolbar,.view-caption{display:flex;align-items:center;gap:12px}.workbench-header{justify-content:space-between;flex-wrap:wrap}.heading a{color:var(--muted);margin-right:12px}.heading h1{font-size:21px;font-weight:550;margin:3px 0}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent)}.revision{background:#26353c;padding:4px 9px;border-radius:4px;font-size:12px}.status{color:var(--muted);font-size:12px}button,input,select,textarea{font:inherit}button{background:#25343b;border:1px solid var(--line);border-radius:4px;padding:7px 12px;color:var(--text);cursor:pointer}button:hover{border-color:#92b0aa}button:disabled{opacity:.42;cursor:default}button.primary{background:var(--accent);color:#122516;border-color:var(--accent)}input,select,textarea{background:#131c21;color:var(--text);border:1px solid var(--line);border-radius:4px;padding:8px;min-width:0}input:focus,textarea:focus,select:focus{outline:1px solid var(--accent)}.workbench-tabs{display:flex;align-items:center;gap:5px;border-bottom:1px solid var(--line);margin:20px 0 0;padding-bottom:10px;overflow-x:auto}.workbench-tabs button{border:0;background:transparent;color:var(--muted);white-space:nowrap}.workbench-tabs button.active{background:#2b4039;color:var(--accent)}.workbench-tabs a{margin-left:auto;white-space:nowrap;color:var(--muted);font-size:12px}.workbench-content{display:grid;grid-template-columns:minmax(0,1fr) 270px;min-height:780px;gap:16px;padding-top:16px}.workspace{min-width:0;border:1px solid var(--line);border-radius:6px;overflow:hidden;background:var(--panel)}.studio-view{height:900px;display:flex;flex-direction:column}.view-caption{justify-content:space-between;font-size:12px;padding:10px;color:var(--muted)}.studio-view iframe{width:100%;flex:1;border:0;min-height:750px}.project-sidebar{display:flex;flex-direction:column;gap:20px;max-height:960px;overflow-y:auto}.project-sidebar section{border-top:1px solid var(--line);padding-top:14px}.project-sidebar h2{font-size:15px;margin:0}.sidebar-heading{margin-bottom:12px}.sidebar-heading button{margin-left:auto;font-size:12px}.asset-row{display:flex;gap:8px;margin-bottom:12px;align-items:center}.asset-row img,.audio-icon{width:54px;height:40px;object-fit:cover;border-radius:4px;background:#26343c;flex-shrink:0}.audio-icon{display:grid;place-items:center}.asset-row strong{display:block;font-size:12px;overflow:hidden;max-width:170px;text-overflow:ellipsis;white-space:nowrap}.asset-row small,.asset-row code{display:block;font-size:10px;color:var(--muted)}.asset-row code{word-break:break-all;font-family:Consolas,monospace;font-size:9px}.agent-panel p,.model-panel p,.template-view>p{color:var(--muted);font-size:12px;line-height:1.7}.agent-panel textarea,.model-panel textarea{width:100%;height:95px;resize:vertical;margin:8px 0}.agent-panel>button,.model-panel>button,.model-panel>select{width:100%;margin:4px 0}.chat-message{background:#293a3a;padding:10px;border-radius:4px;font-size:12px;line-height:1.6;white-space:pre-wrap;margin:8px 0}.source-view{display:grid;grid-template-columns:190px minmax(0,1fr);min-height:850px}.file-list{padding:14px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:8px}.file-list>button,.catalog-view aside>button{text-align:left;word-break:break-all;background:transparent;border:0;padding:9px}.file-list>button.selected,.catalog-view button.selected{background:#2a403b;color:var(--accent)}.file-list label{font-size:12px;color:var(--muted)}.file-list select{width:100%;margin:8px 0}.new-file{display:flex;gap:4px}.new-file input{width:120px;font-size:11px}.file-list p{font-size:11px;line-height:1.8;color:var(--muted)}.code-pane{display:flex;flex-