ersion-row{display:flex;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding:15px 0}.version-row>span{color:var(--accent)}.version-row p{flex:1;font-size:12px;margin:0}.version-row small{color:var(--muted);font-size:10px}@media(max-width:1100px){.workbench-content{grid-template-columns:minmax(0,1fr)}.project-sidebar{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-height:none}.workbench-header .actions{flex-wrap:wrap}}@media(max-width:700px){.hypit-workbench{padding:12px;margin:-16px}.source-view,.catalog-view{grid-template-columns:140px minmax(0,1fr)}.project-sidebar{display:block}.template-grid{grid-template-columns:1fr}.code-toolbar{flex-wrap:wrap}.studio-view{overflow:auto}.studio-view iframe{min-width:1050px}.version-row{flex-wrap:wrap}}
